        this.mainBranch = mainBranch;
        this.subBranch = subBranch;
        this.additionalBranch = additionalBranch;
    }

    @ManyToOne
    private Branch mainBranch;

    @ManyToOne
    private Branch subBranch;

    @ManyToOne
    private Branch additionalBranch;

