    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public List<DeptEmployee> getEmployees() {
        return employees;
    }

    public void setEmployees(List<DeptEmployee> employees) {
        this.employees = employees;
    }
}

